// @ts-ignore
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

const manifestText = buffer.toString('utf8');
let documents;

try {
  documents = JSON.parse(manifestText);
} catch (error) {
  throw new Error('documents.json could not be parsed. Please check JSON syntax.');
}

if (!Array.isArray(documents)) {
  throw new Error('documents.json must contain an array of document definitions.');
}

const requiredFields = ['document_id', 'title', 'category', 'file_name'];

return documents.map((document, index) => {
  for (const field of requiredFields) {
    if (!document[field]) {
      throw new Error(`Missing required field "${field}" in documents.json item ${index + 1}`);
    }
  }

  const relativeFilePath = document.file_path
    ? String(document.file_path).replace(/^data\//, '')
    : `mock-data/${document.file_name}`;

  return {
    json: {
      document_id: document.document_id,
      title: document.title,
      category: document.category,
      file_name: document.file_name,
      file_type: document.file_type || null,
      source_file_name: document.source_file_name || document.file_name,
      content_hash: document.content_hash || null,
      last_updated: document.last_updated || null,
      file_path: `/home/node/.n8n-files/data/${relativeFilePath}`
    }
  };
});

const items = $input.all();
const fileListItems = $('Create File List').all();
const output = [];

// ============================================================
// METİN TEMİZLİĞİ
// ============================================================

function cleanText(text) {
  return String(text || '')
    // İşlenmiş dosyalardaki metadata yorumlarını kaldırır.
    .replace(/<!--[\s\S]*?-->/g, '')

    // Satır sonlarını standartlaştırır.
    .replace(/\r\n/g, '\n')

    // Fazla boş satırları temizler.
    .replace(/\n{3,}/g, '\n\n')

    .trim();
}

// ============================================================
// HER DOSYAYI BÖLÜMLERE AYIR
// ============================================================

for (
  let itemIndex = 0;
  itemIndex < items.length;
  itemIndex++
) {
  const metadata = fileListItems[itemIndex]?.json;

  if (!metadata?.document_id) {
    throw new Error(
      `Document metadata not found for item index ${itemIndex}`
    );
  }

  // Read Files from Disk node'undan binary dosyayı okur.
  // @ts-ignore
  const buffer =
    await this.helpers.getBinaryDataBuffer(
      itemIndex,
      'data'
    );

  const fileContent = cleanText(
    buffer.toString('utf8')
  );

  const lines = fileContent.split('\n');

  // Dokümandaki H1 başlıklarını bulur.
  // İşlenmiş dosyalarda birden fazla H1 varsa
  // son H1 genellikle Türkçe ve açıklayıcı başlıktır.
  const h1Titles = lines
    .map((line) => {
      const match = line.match(/^#\s+(.+)$/);

      return match
        ? match[1].trim()
        : null;
    })
    .filter(Boolean);

  const documentHeading =
    h1Titles[h1Titles.length - 1] ||
    metadata.title ||
    metadata.document_id;

  let currentSectionTitle = 'Genel';
  let currentLines = [];
  let chunkIndex = 1;

  // ==========================================================
  // MEVCUT BÖLÜMÜ OUTPUT'A EKLE
  // ==========================================================

  function pushSection() {
    const content = cleanText(
      currentLines.join('\n')
    );

    if (!content) {
      return;
    }

    /*
     * EmbeddingGemma için kullanılan metin:
     *
     * title:
     *   Doküman başlığı + bölüm başlığı
     *
     * text:
     *   Bölümün gerçek içeriği
     *
     * Örnek:
     *
     * title: IT Destek Kaydı Oluşturma ve Takip Süreci -
     * Destek kaydında bulunması gereken bilgiler
     * |
     * text: Kullanıcı adı, sicil numarası...
     */

    const embeddingTitle = [
      documentHeading,
      currentSectionTitle
    ]
      .filter(Boolean)
      .join(' - ');

    const embeddingText =
      `title: ${embeddingTitle} | text: ${content}`;

    output.push({
      json: {
        // Default Data Loader bu alanı embedding'e gönderir.
        text: embeddingText,

        metadata: {
          document_id:
            metadata.document_id,

          // Frontend ve kaynak gösterimi için
          // mevcut manifest başlığını koruyoruz.
          title:
            metadata.title,

          category:
            metadata.category,

          section_title:
            currentSectionTitle,

          chunk_index:
            chunkIndex,

          file_name:
            metadata.file_name,

          source_file_name:
            metadata.source_file_name ||
            metadata.file_name,

          file_type:
            metadata.file_type || null,

          content_hash:
            metadata.content_hash || null,

          last_updated:
            metadata.last_updated || null
        }
      }
    });

    chunkIndex++;
  }

  // ==========================================================
  // SATIRLARI İŞLE
  // ==========================================================

  for (const line of lines) {
    const sectionMatch =
      line.match(/^##\s+(.+)$/);

    if (sectionMatch) {
      // Yeni bölüme geçmeden önce önceki bölümü kaydet.
      pushSection();

      currentSectionTitle =
        sectionMatch[1].trim();

      /*
       * ## başlığını content içine tekrar eklemiyoruz.
       * Bölüm başlığı zaten embeddingTitle içinde bulunuyor.
       */
      currentLines = [];

      continue;
    }

    /*
     * # ana başlıkları bölüm içeriğine eklemiyoruz.
     * Doküman başlığı zaten embeddingTitle içinde bulunuyor.
     */
    if (/^#\s+/.test(line)) {
      continue;
    }

    currentLines.push(line);
  }

  // Dosyanın son bölümünü de kaydet.
  pushSection();
}

return output;
